import { z } from 'zod';
import type { AgentRunner } from '../src/ai/runtime/agent-runner.js';
import type { AiCredentials } from '../src/ai/settings/ai.service.js';

const PROMPT = [
  'You judge campaign pitches generated by a tabletop RPG app. The app must fit any genre, not only medieval fantasy.',
  'You receive the requested theme, the moods, the expected genre and the pitches.',
  'Score each pitch from 1 to 5, in the same order:',
  '- genre: how well the world, its scale, its powers and its conflicts fit the expected genre. 1 reads like another genre, 5 could only be this genre.',
  '- tone: how well the kind of story fits the moods and the genre. Horror builds dread, a school story centers on social stakes.',
  '- playable: how many concrete things a player can do, chase or fear right away.',
  'List in leaks the elements that belong to another genre, such as kingdoms, rulers, creatures or magic in a school story. Empty when none.',
  'Score variety from 1 to 5: how different the pitches are from each other.',
  'Be strict: 3 is average and 5 is rare.',
].join('\n');

const score = z.number().int().min(1).max(5);

const verdictSchema = z.object({
  pitches: z.array(
    z.object({
      genre: score,
      tone: score,
      playable: score,
      leaks: z.array(z.string()),
    }),
  ),
  variety: score,
});

export type Verdict = z.infer<typeof verdictSchema>;

const OUTPUT = {
  name: 'submit_verdict',
  description: 'Submits the verdict.',
  input: verdictSchema,
};

export interface JudgeInput {
  theme: string;
  moods: string[];
  direction?: string;
  expect: string;
  pitches: unknown[];
}

export function judge(
  runner: AgentRunner,
  credentials: AiCredentials,
  input: JudgeInput,
): Promise<Verdict> {
  return runner.submit(
    credentials,
    [
      { role: 'system', content: PROMPT },
      {
        role: 'user',
        content: [
          `Theme: ${input.theme}`,
          `Moods: ${input.moods.join(', ') || 'none'}`,
          input.direction ? `Player direction: ${input.direction}` : null,
          `Expected genre: ${input.expect}`,
          ...input.pitches.map(
            (pitch, index) =>
              `Pitch ${index + 1}:\n${JSON.stringify(pitch, null, 2)}`,
          ),
        ]
          .filter((part) => part !== null)
          .join('\n\n'),
      },
    ],
    OUTPUT,
  );
}
